"use client";

import { motion, useReducedMotion } from "motion/react";
import type { ComponentProps } from "react";

export type TypewriterPrimitiveProps = ComponentProps<typeof motion.div>;

export function TypewriterPrimitive({ children, ...props }: TypewriterPrimitiveProps) {
  const reduceMotion = useReducedMotion();

  return (
    <motion.div
      {...props}
      initial={reduceMotion ? false : {clipPath: "inset(0 100% 0 0)"}}
      animate={{clipPath: "inset(0 0% 0 0)"}}
      transition={reduceMotion ? { duration: 0.12 } : { duration: 1.2, ease: [0.23, 1, 0.32, 1] }}

    >
      {children}
    </motion.div>
  );
}
